	/** 
	 * jumpstart the process by instantiating2 Claim
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		claimId = ClaimService.getClaimInstance()
		.createClaim( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ClaimService.getClaimInstance()
				.createClaim( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.claimSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Claim : " + successValue.getClaimId());
							  if (successValue.getClaimId().equals(claimId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfClaimList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Claim test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on claim consumed")
					);
			subscriber.claimSubscribe( claimId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Claim : " + successValue.getClaimId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfClaimList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on claim for claimId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Claim. 
	 */
	protected Claim read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Claim" );

		Claim entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Claim with primary key" );
		msg.append( claimId );
		
		ClaimFetchOneSummary fetchOneSummary = new ClaimFetchOneSummary( claimId );

		try {
			entity = ClaimService.getClaimInstance().getClaim( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Claim " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Claim.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Claim." );

		StringBuilder msg = new StringBuilder( "Failed to update a Claim : " );        
		Claim entity = read();
		UpdateClaimCommand command = generateUpdateCommand();
		command.setClaimId(entity.getClaimId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Claim." );

			// for use later on...
			claimId = entity.getClaimId();

			ClaimService proxy = ClaimService.getClaimInstance();  

			proxy.updateClaim( command ).get();

			LOGGER.info( "-- Successfully saved Claim - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + claimId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Claim.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Claim." );

		Claim entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Claim with id " + claimId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Claim with id " + claimId );

			throw e;
		}

		try{
			ClaimService.getClaimInstance().delete( new DeleteClaimCommand( entity.getClaimId() ) ).get();
			LOGGER.info( "-- Successfully deleted Claim with id " + claimId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Claim with id " + claimId );

			throw e;
		}
	}

	/**
	 * get all Claims.
	 */
	protected List<Claim> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Claims:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Claim : " );        
		List<Claim> collection  = new ArrayList<>();

		try {
			// call the static get method on the ClaimService
			collection = ClaimService.getClaimInstance().getAllClaim();
			assertNotNull( collection, "An Empty collection of Claim was incorrectly returned.");
			
			// Now print out the values
			Claim entity = null;            
			Iterator<Claim> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getClaimId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

